'use strict';
/**
 * Builds the paste-in file for the stores' script manager from the two sources in docs/account-brand/:
 *
 *   account-brand.css + account-brand.js  ->  account-brand-entry.html   (the box CONTENT: <style> + <script>, ONE entry, pasted identically in all 5 stores)
 *                                         ->  preview-snippet.js         (the same CSS + JS for the browser console; previews in one tab only)
 *
 *   node scripts/build-account-brand-entry.js            write both files
 *   node scripts/build-account-brand-entry.js --check    exit 1 if a generated file is stale or a guard fails (PR check)
 *
 * Guards (the entry is pasted into a theme that renders every store page, so a leak would not stay on the account pages):
 *   - every rule selector starts with the :has(...) account scope (only :root, @import, @media and comments are exempt);
 *   - no "</style" / "</script" inside the content (it would end the box early); CSS braces balance; the JS parses;
 *   - no @import in the CSS (fonts are added by the JS, on /account/* only) and the JS keeps its path gate; the CSS declares the version (--mo-account-skin).
 * Docs: docs/account-brand/README.md, docs/store-account-area.md.
 */
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const DIR = path.join(__dirname, '..', 'docs', 'account-brand');
const css = fs.readFileSync(path.join(DIR, 'account-brand.css'), 'utf8');
const js = fs.readFileSync(path.join(DIR, 'account-brand.js'), 'utf8');
const SCOPE = 'html body:has(#customer_login,#customer_register,#account_default,#account_orders,#account_orderDetail)';

const problems = [];
const version = (css.match(/--mo-account-skin:\s*(v\d+)/) || [])[1];
if (!version) problems.push('the CSS must declare :root { --mo-account-skin: vN } (the probe reads it to tell which stores have the entry)');

// selector scope: every line that opens or continues a selector list
css.replace(/\/\*[\s\S]*?\*\//g, m => ' '.repeat(m.length)).split('\n').forEach((raw, i) => {
  const line = raw.trim();
  if (!line || !/[,{]$/.test(line)) return;
  if (line.startsWith('@') || line.startsWith(':root') || line.startsWith('}') || /^[a-z-]+\s*:/i.test(line) && !line.startsWith('html')) return;
  if (!line.startsWith(SCOPE)) problems.push(`css line ${i + 1}: selector without the account scope: ${line.slice(0, 90)}`);
});
const stripped = css.replace(/\/\*[\s\S]*?\*\//g, '');
if ((stripped.match(/{/g) || []).length !== (stripped.match(/}/g) || []).length) problems.push('css: unbalanced braces');
if (/@import/.test(stripped)) problems.push('css: no @import (it would load fonts on every store page; the JS adds the font link on /account/* only)');
if (!/\/\^\\\/account/.test(js)) problems.push('js: the /account path gate is missing');
if (/<\/style/i.test(css)) problems.push('css contains </style');
if (/<\/script/i.test(js)) problems.push('js contains </script');
try { new vm.Script(js); } catch (e) { problems.push('js does not parse: ' + e.message); }

const entry = `<!-- MOMUTO account skin ${version} — script-manager entry, box CONTENT (the platform adds its own start/end markers).
     GENERATED by scripts/build-account-brand-entry.js from docs/account-brand/account-brand.css + account-brand.js — do not edit here.
     Paste this whole file as ONE new entry named "MOMUTO account skin ${version}" in EACH of the 5 stores (www, us, es, fr, it), identical.
     Restyles /account/login, /account/register, /account, /account/orders, /account/orders/<id> and moves the tracking number to the top of the order page.
     Every CSS rule is scoped with :has() to those pages and the script returns at once anywhere outside /account/ (no fonts, no observer). To undo: disable or delete this entry. Docs: docs/account-brand/README.md -->
<style>
${css.trim()}
</style>
<script>
${js.trim()}
</script>
`;
const preview = `/* MOMUTO account skin ${version} — PREVIEW ONLY. Paste this whole file into the browser console (F12 > Console) on a store account page,
 * e.g. us.momuto.com/account/orders/<your order>, /account, /account/login. It styles THIS TAB ONLY; reload and it is gone.
 * GENERATED by scripts/build-account-brand-entry.js from account-brand.css + account-brand.js. */
(function () {
  var st = document.createElement('style'); st.id = 'mo-account-preview';
  st.textContent = ${JSON.stringify(css.trim())};
  document.head.appendChild(st);
${js.trim()}
})();
`;

const out = { 'account-brand-entry.html': entry, 'preview-snippet.js': preview };
if (problems.length) { console.error('account-brand guard FAILED:\n  - ' + problems.join('\n  - ')); process.exit(1); }
if (process.argv.includes('--check')) {
  const stale = Object.keys(out).filter(f => !fs.existsSync(path.join(DIR, f)) || fs.readFileSync(path.join(DIR, f), 'utf8') !== out[f]);
  if (stale.length) { console.error('stale generated file(s): ' + stale.join(', ') + '\nRun: node scripts/build-account-brand-entry.js (and commit)'); process.exit(1); }
  console.log(`account-brand: entry + preview are current (${version}, ${Buffer.byteLength(entry)} bytes).`);
} else {
  Object.entries(out).forEach(([f, c]) => fs.writeFileSync(path.join(DIR, f), c));
  console.log(`account-brand: wrote account-brand-entry.html (${Buffer.byteLength(entry)} bytes) and preview-snippet.js, version ${version}.`);
}
